"""Sivand-style reducer and attribution helpers."""

from __future__ import annotations

from dataclasses import dataclass

from reduction.grammar import Grammar
from reduction.perses_reducer import PersesReducer
from reduction.sivand.attention_priority import AttentionExtractor, AttentionPriorityQueue
from reduction.sivand.model_oracle import MockModel, ModelOracle, ModelPrediction
from reduction.tree import NodeType, SparTreeNode
from reduction.tree_utils import iter_nodes, node_at, rewrite_source_tokens


@dataclass(frozen=True)
class SaliencyEntry:
    token: str
    line: int
    col: int
    importance: float
    essential: bool


@dataclass
class SaliencyMap:
    """Per-token importance scores for the original source."""

    entries: list[SaliencyEntry]

    @property
    def essential_count(self) -> int:
        return sum(1 for entry in self.entries if entry.essential)

    def essential_entries(self) -> list[SaliencyEntry]:
        return [entry for entry in self.entries if entry.essential]


@dataclass
class MinimalExplanation:
    """Reduced program plus attribution metadata."""

    minimal_source: str
    prediction: ModelPrediction
    original_tokens: int
    minimal_tokens: int
    oracle_calls: int
    saliency_map: SaliencyMap
    ranked_features: list[SaliencyEntry]

    @property
    def reduction_ratio(self) -> float:
        if self.original_tokens == 0:
            return 0.0
        return 1.0 - (self.minimal_tokens / self.original_tokens)

    @property
    def sparsity(self) -> float:
        if self.original_tokens == 0:
            return 0.0
        return 1.0 - (self.saliency_map.essential_count / self.original_tokens)


class SivandReducer(PersesReducer):
    """Perses reducer with optional attention-guided prioritization."""

    def __init__(
        self,
        grammar: Grammar,
        model: MockModel | None = None,
        use_attention_priority: bool = True,
    ):
        super().__init__(grammar)
        self.model = model or MockModel()
        self.use_attention_priority = use_attention_priority
        self.attention_extractor = AttentionExtractor(self.model)

    @property
    def name(self) -> str:
        return "sivand"

    def _reduce_once(
        self,
        tree: SparTreeNode,
        tester: ModelOracle,
    ) -> SparTreeNode | None:
        if not self.use_attention_priority:
            return super()._reduce_once(tree, tester)

        source = tree.to_source()
        prediction = tester.cached_prediction(source)
        attention_map = self.attention_extractor.extract(source, prediction)
        queue = AttentionPriorityQueue(self.attention_extractor, attention_map)

        for order, (path, node) in enumerate(iter_nodes(tree)):
            if node.deleted or node.node_type == NodeType.TOKEN or node.token_count() == 0:
                continue
            queue.push(path, node, order)

        while queue:
            path = queue.pop()
            node = node_at(tree, path)
            if node is None or node.deleted or node.token_count() == 0:
                continue

            if self._is_list_node(node):
                candidate = self._reduce_list_children(tree, path, tester)
            elif node.node_type == NodeType.OPTIONAL:
                candidate = self._delete_whole_node(tree, path, tester)
            elif node.node_type == NodeType.REGULAR:
                candidate = self._replace_with_compatible_descendant(tree, path, tester)
            else:
                candidate = None

            if candidate is not None and candidate.token_count() < tree.token_count():
                return candidate

        return None


class IterativeAttributor:
    """Estimate token importance by removing tokens one at a time."""

    def __init__(self, model: MockModel | None = None):
        self.model = model or MockModel()

    def attribute(self, source: str, oracle: ModelOracle) -> SaliencyMap:
        original_prediction = oracle.cached_prediction(source)
        tokens = [
            token
            for token in self.model.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]

        entries: list[SaliencyEntry] = []
        for token in tokens:
            candidate = rewrite_source_tokens(
                source,
                lambda current, token=token: ""
                if (
                    current.line == token.line
                    and current.col == token.col
                    and current.value == token.value
                )
                else None,
            )
            stable = oracle.test(candidate)
            candidate_prediction = oracle.cached_prediction(candidate)
            confidence_drop = max(
                0.0,
                original_prediction.confidence - candidate_prediction.confidence,
            )
            importance = 1.0 + confidence_drop if not stable else confidence_drop
            entries.append(
                SaliencyEntry(
                    token=token.value,
                    line=token.line,
                    col=token.col,
                    importance=importance,
                    essential=not stable,
                )
            )

        return SaliencyMap(entries)

