"""Deterministic model oracle used by Sivand-style reductions."""

from __future__ import annotations

from collections import OrderedDict
from dataclasses import dataclass
from hashlib import sha256
from math import exp
from typing import Callable, Iterable

from reduction.property_test import PropertyTester
from reduction.token import Token, Tokenizer


SECURITY_KEYWORDS = {
    "eval",
    "exec",
    "input",
    "open",
    "os",
    "pickle",
    "popen",
    "shell",
    "subprocess",
    "system",
}


@dataclass(frozen=True)
class ModelPrediction:
    """Mock neural model output."""

    label: str
    confidence: float
    logits: dict[str, float]
    attention_weights: list[float]


class PredictionCache:
    """Content-addressed cache with LRU-style eviction."""

    def __init__(self, max_entries: int = 128):
        self.max_entries = max(1, max_entries)
        self._entries: OrderedDict[str, ModelPrediction] = OrderedDict()

    def _key(self, source: str) -> str:
        return sha256(source.encode("utf-8")).hexdigest()

    def get(self, source: str) -> ModelPrediction | None:
        key = self._key(source)
        prediction = self._entries.get(key)
        if prediction is None:
            return None
        self._entries.move_to_end(key)
        return prediction

    def put(self, source: str, prediction: ModelPrediction) -> ModelPrediction:
        key = self._key(source)
        self._entries[key] = prediction
        self._entries.move_to_end(key)
        while len(self._entries) > self.max_entries:
            self._entries.popitem(last=False)
        return prediction

    def get_or_compute(
        self,
        source: str,
        factory: Callable[[str], ModelPrediction],
    ) -> ModelPrediction:
        cached = self.get(source)
        if cached is not None:
            return cached
        return self.put(source, factory(source))


class MockModel:
    """Keyword-based stand-in for a neural code model."""

    def __init__(self) -> None:
        self.tokenizer = Tokenizer()

    def predict(self, source: str) -> ModelPrediction:
        tokens = self._tokens(source)
        attention_weights = [self._attention_for(token) for token in tokens]
        security_hits = sum(1 for token in tokens if self._is_security_token(token))
        vulnerable_logit = -1.5 + (1.8 * security_hits) + sum(attention_weights) * 0.05
        benign_logit = 0.8 + max(0.0, len(tokens) - security_hits) * 0.02

        if vulnerable_logit >= benign_logit:
            label = "vulnerable"
        else:
            label = "benign"

        confidence = self._confidence(vulnerable_logit, benign_logit, label)
        logits = {"benign": benign_logit, "vulnerable": vulnerable_logit}
        return ModelPrediction(label, confidence, logits, attention_weights)

    def batch_predict(self, sources: Iterable[str]) -> list[ModelPrediction]:
        return [self.predict(source) for source in sources]

    def get_feature_importance(self, source: str) -> list[tuple[str, float]]:
        prediction = self.predict(source)
        return sorted(
            [
                (token.value, weight)
                for token, weight in zip(self._tokens(source), prediction.attention_weights)
            ],
            key=lambda item: item[1],
            reverse=True,
        )

    def _tokens(self, source: str) -> list[Token]:
        return [
            token
            for token in self.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]

    def _attention_for(self, token: Token) -> float:
        value = token.value.lower()
        if self._is_security_token(token):
            return 0.98
        if token.type == "KEYWORD" and value in {"import", "from", "return", "raise"}:
            return 0.45
        if token.type == "IDENTIFIER":
            return 0.22
        if token.type in {"STRING", "FSTRING"}:
            return 0.18
        if token.type == "NUMBER":
            return 0.08
        if token.type == "INDENT":
            return 0.03
        if token.type in {"OPERATOR", "DELIMITER"}:
            return 0.02
        return 0.05

    def _is_security_token(self, token: Token) -> bool:
        value = token.value.lower()
        if value in SECURITY_KEYWORDS:
            return True
        return token.type in {"STRING", "COMMENT"} and any(
            keyword in value
            for keyword in SECURITY_KEYWORDS
        )

    def _confidence(self, vulnerable_logit: float, benign_logit: float, label: str) -> float:
        vuln_score = exp(vulnerable_logit)
        benign_score = exp(benign_logit)
        total = vuln_score + benign_score
        if total == 0:
            return 0.5
        if label == "vulnerable":
            return vuln_score / total
        return benign_score / total


class ModelOracle(PropertyTester):
    """Property tester that preserves a target model prediction."""

    def __init__(
        self,
        model: MockModel,
        target_label: str,
        cache: PredictionCache | None = None,
    ) -> None:
        self.model = model
        self.target_label = target_label
        self.cache = cache or PredictionCache()
        self._test_count = 0
        self.test_script = ""
        self.work_dir = ""
        self.timeout = 0

    def cached_prediction(self, source: str) -> ModelPrediction:
        return self.cache.get_or_compute(source, self.model.predict)

    def test(self, program_source: str) -> bool:
        self._test_count += 1
        return self.cached_prediction(program_source).label == self.target_label

