"""Attention-guided prioritization for Sivand reducers."""

from __future__ import annotations

import heapq

from reduction.sivand.model_oracle import MockModel, ModelPrediction
from reduction.tree import SparTreeNode


class AttentionExtractor:
    """Derive token and subtree attention from the mock model."""

    def __init__(self, model: MockModel):
        self.model = model

    def extract(
        self,
        source: str,
        prediction: ModelPrediction | None = None,
    ) -> dict[tuple[int, int, str], float]:
        prediction = prediction or self.model.predict(source)
        tokens = [
            token
            for token in self.model.tokenizer.tokenize(source)
            if token.type != "NEWLINE"
        ]
        return {
            (token.line, token.col, token.value): weight
            for token, weight in zip(tokens, prediction.attention_weights)
        }

    def node_attention(
        self,
        node: SparTreeNode,
        attention_map: dict[tuple[int, int, str], float],
    ) -> float:
        weights = [
            attention_map.get((token.line, token.col, token.value), 0.0)
            for token in node.tokens()
            if token.type != "NEWLINE"
        ]
        if not weights:
            return 0.0
        return sum(weights) / len(weights)


class AttentionPriorityQueue:
    """Priority queue that prefers low-attention nodes before large ones."""

    def __init__(
        self,
        extractor: AttentionExtractor,
        attention_map: dict[tuple[int, int, str], float],
    ) -> None:
        self.extractor = extractor
        self.attention_map = attention_map
        self._heap: list[tuple[float, int, int, tuple[int, ...]]] = []

    def push(self, path: tuple[int, ...], node: SparTreeNode, order: int) -> None:
        priority = (
            self.extractor.node_attention(node, self.attention_map),
            -node.token_count(),
            order,
            path,
        )
        heapq.heappush(self._heap, priority)

    def pop(self) -> tuple[int, ...]:
        return heapq.heappop(self._heap)[-1]

    def __bool__(self) -> bool:
        return bool(self._heap)

