"""Sivand reduction and attribution built on top of Perses."""

from __future__ import annotations

from dataclasses import dataclass

from reduction.grammar import Grammar
from reduction.perses_reducer import PersesReducer
from reduction.sivand.attention_priority import AttentionExtractor, AttentionPriorityQueue
from reduction.sivand.model_oracle import MockModel, ModelOracle, ModelPrediction
from reduction.tree import NodeType, SparTreeNode
from reduction.tree_utils import node_at, rewrite_source_tokens


@dataclass(frozen=True)
class SaliencyEntry:
    """Importance assigned to a token in the original program."""

    index: int
    token_value: str
    token_type: str
    line: int
    col: int
    importance: float
    attention: float
    essential: bool


@dataclass
class SaliencyMap:
    """Token-level importance map for the original source program."""

    entries: list[SaliencyEntry]

    @property
    def essential_count(self) -> int:
        return sum(1 for entry in self.entries if entry.essential)

    @property
    def removable_count(self) -> int:
        return len(self.entries) - self.essential_count

    @property
    def sparsity(self) -> float:
        if not self.entries:
            return 0.0
        return 1.0 - (self.essential_count / len(self.entries))

    def score_by_index(self) -> dict[int, float]:
        return {
            entry.index: entry.importance
            for entry in self.entries
        }

    def essential_entries(self) -> list[SaliencyEntry]:
        return [entry for entry in self.entries if entry.essential]


@dataclass
class MinimalExplanation:
    """Full Sivand result bundle."""

    original_source: str
    minimal_source: str
    prediction: ModelPrediction
    reduction_stats: dict[str, int | float]
    saliency_map: SaliencyMap
    feature_ranking: list[tuple[int, str, float]]

    @property
    def original_tokens(self) -> int:
        return int(self.reduction_stats.get("original_tokens", 0))

    @property
    def minimal_tokens(self) -> int:
        return int(self.reduction_stats.get("minimal_tokens", 0))

    @property
    def oracle_calls(self) -> int:
        return int(self.reduction_stats.get("oracle_calls", 0))

    @property
    def essential_count(self) -> int:
        return self.saliency_map.essential_count

    @property
    def sparsity(self) -> float:
        return self.saliency_map.sparsity

    @property
    def ranked_features(self) -> list[tuple[int, str, float]]:
        return self.feature_ranking


class IterativeAttributor:
    """Assign token importance by single-token removal tests."""

    def __init__(self, oracle: ModelOracle):
        self.oracle = oracle

    def attribute(self, source: str) -> SaliencyMap:
        features = self.oracle.model.get_feature_importance(source)
        entries: list[SaliencyEntry] = []

        for index, (token, attention) in enumerate(features):
            candidate_source = rewrite_source_tokens(
                source,
                lambda current, token=token: ""
                if self._same_token(current, token)
                else None,
            )
            essential = not self.oracle.test(candidate_source)
            entries.append(
                SaliencyEntry(
                    index=index,
                    token_value=token.value,
                    token_type=token.type,
                    line=token.line,
                    col=token.col,
                    importance=1.0 if essential else 0.0,
                    attention=attention,
                    essential=essential,
                )
            )

        return SaliencyMap(entries)

    def _same_token(self, left, right) -> bool:
        return (
            left.line == right.line
            and left.col == right.col
            and left.type == right.type
            and left.value == right.value
        )


class SivandReducer(PersesReducer):
    """Perses-style reducer with optional attention-guided node priority."""

    def __init__(
        self,
        grammar: Grammar,
        model: MockModel | None = None,
        use_attention_priority: bool = True,
    ):
        super().__init__(grammar)
        self.model = model or MockModel()
        self.use_attention_priority = use_attention_priority
        self.extractor = AttentionExtractor(self.model)

    @property
    def name(self) -> str:
        return "sivand_perses"

    def _reduce_once(
        self,
        tree: SparTreeNode,
        tester,
    ) -> SparTreeNode | None:
        if not self.use_attention_priority:
            return super()._reduce_once(tree, tester)

        source = tree.to_source()
        prediction = tester.predict(source) if hasattr(tester, "predict") else self.model.predict(source)
        attention = self.extractor.node_attention(tree, source, prediction)
        queue = AttentionPriorityQueue.build(tree, attention)

        while queue:
            path = queue.pop()
            node = node_at(tree, path)
            if node is None or node.deleted or node.node_type == NodeType.TOKEN or node.token_count() == 0:
                continue

            if self._is_list_node(node):
                candidate = self._reduce_list_children(tree, path, tester)
            elif node.node_type == NodeType.OPTIONAL:
                candidate = self._delete_whole_node(tree, path, tester)
            elif node.node_type == NodeType.REGULAR:
                candidate = self._replace_with_compatible_descendant(tree, path, tester)
            else:
                candidate = None

            if candidate is not None and candidate.token_count() < tree.token_count():
                return candidate

        return None
